package com.example.TuVanSinhVien.service;

import com.example.TuVanSinhVien.entity.*;
import com.example.TuVanSinhVien.repository.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;

@Service
public class AppointmentService {
    private final KhungGioTuVanRepository slotRepo;
    private final LichHenTuVanRepository appointmentRepo;
    private final DanhGiaBuoiTuVanRepository ratingRepo;
    private final NotificationService notificationService;

    @Transactional
    public KhungGioTuVan createSlot(NguoiTuVan cv, LocalDateTime start, LocalDateTime end, String hinhThuc, String diaDiemLink) {
        if (start == null || end == null || start.isBefore(LocalDateTime.now().plusMinutes(15))) {
            throw new IllegalArgumentException("Khung giờ phải bắt đầu trong tương lai và cách hiện tại ít nhất 15 phút.");
        }
        if (end.isBefore(start) || end.isEqual(start)) {
            throw new IllegalArgumentException("Thời gian kết thúc phải sau thời gian bắt đầu.");
        }
        long minutes = ChronoUnit.MINUTES.between(start, end);
        if (minutes != 45 && minutes != 60) {
            throw new IllegalArgumentException("Thời lượng khung giờ tư vấn phải đúng 45 hoặc 60 phút.");
        }
        if (!"TrucTuyen".equals(hinhThuc) && !"TrucTiep".equals(hinhThuc)) {
            throw new IllegalArgumentException("Hình thức tư vấn chỉ có thể là TrucTuyen hoặc TrucTiep.");
        }
        if (diaDiemLink == null || diaDiemLink.trim().isEmpty()) {
            throw new IllegalArgumentException("Vui lòng nhập liên kết hoặc địa điểm tư vấn.");
        }
        if (slotRepo.existsOverlappingSlot(cv.getMaCV(), start, end)) {
            throw new IllegalArgumentException("Khung giờ bị trùng hoặc giao nhau với khung giờ khác của bạn.");
        }
        KhungGioTuVan slot = KhungGioTuVan.builder().nguoiTuVan(cv).batDau(start).ketThuc(end).hinhThuc(hinhThuc).diaDiemLink(diaDiemLink).trangThai("Mo").build();
        return slotRepo.save(slot);
    }

    public List<KhungGioTuVan> getAvailableSlots(Integer maCV) {
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime endWindow = now.plusDays(7);
        List<KhungGioTuVan> slots;
        if (maCV != null && maCV > 0) {
            slots = slotRepo.findAvailableSlotsByAdvisor(maCV, now, endWindow);
        } else {
            slots = slotRepo.findAvailableSlotsWithinWindow(now, endWindow);
        }
        // Lọc bỏ slot đã có người đặt chiếm chỗ
        List<KhungGioTuVan> result = new ArrayList<>();
        for (KhungGioTuVan s : slots) {
            if (!appointmentRepo.isSlotOccupied(s.getMaKhungGio())) {
                result.add(s);
            }
        }
        return result;
    }

    @Transactional
    public LichHenTuVan bookAppointment(SinhVien sv, Integer maKhungGio, String chuDe, String noiDungHen) {
        if (chuDe == null || chuDe.trim().isEmpty()) {
            throw new IllegalArgumentException("Chủ đề hẹn tư vấn không được để trống.");
        }
        if (noiDungHen == null || noiDungHen.trim().isEmpty()) {
            throw new IllegalArgumentException("Nội dung chi tiết buổi hẹn không được để trống.");
        }
        // Quy tắc: tối đa 2 lịch chờ duyệt trên mỗi sinh viên
        long pendingCount = appointmentRepo.countPendingByStudent(sv.getMaSV());
        if (pendingCount >= 2) {
            throw new IllegalStateException("Bạn đã có 2 lịch hẹn đang chờ duyệt. Vui lòng đợi cố vấn xử lý trước khi đặt thêm.");
        }
        KhungGioTuVan slot = slotRepo.findById(maKhungGio).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy khung giờ tư vấn."));
        if (!"Mo".equals(slot.getTrangThai())) {
            throw new IllegalStateException("Khung giờ tư vấn này hiện đang bị khóa.");
        }
        LocalDateTime now = LocalDateTime.now();
        if (slot.getBatDau().isBefore(now)) {
            throw new IllegalStateException("Không thể đặt khung giờ trong quá khứ.");
        }
        if (slot.getBatDau().isAfter(now.plusDays(7))) {
            throw new IllegalStateException("Chỉ được đặt lịch trong vòng 7 ngày tới.");
        }
        // Kiểm tra slot đã kín chưa
        if (appointmentRepo.isSlotOccupied(maKhungGio)) {
            throw new IllegalStateException("Khung giờ này vừa có người đặt trước. Vui lòng chọn khung giờ khác.");
        }
        // Kiểm tra sinh viên có bị trùng lịch hẹn khác cùng thời gian không
        if (appointmentRepo.existsOverlappingStudentAppointment(sv.getMaSV(), slot.getBatDau(), slot.getKetThuc())) {
            throw new IllegalStateException("Bạn đã có một lịch hẹn khác trong khoảng thời gian này.");
        }
        LichHenTuVan appointment = LichHenTuVan.builder().sinhVien(sv).nguoiTuVan(slot.getNguoiTuVan()).khungGio(slot).chuDe(chuDe.trim()).noiDungHen(noiDungHen.trim()).trangThai("ChoDuyet").ngayTao(now).hanDuyet(now.plusHours(24)).build();
        appointment = appointmentRepo.save(appointment);
        // Báo cho cố vấn
        notificationService.sendNotification(slot.getNguoiTuVan().getTaiKhoan(), "Có yêu cầu đặt lịch hẹn mới", "Sinh viên " + sv.getTaiKhoan().getHoTen() + " vừa đặt lịch hẹn: \'" + chuDe + "\'.", "LichHen", "/advisor/appointments");
        return appointment;
    }

    @Transactional
    public void approveAppointment(Integer maLichHen, Integer maCV, String linkHopPhong) {
        if (linkHopPhong == null || linkHopPhong.trim().isEmpty()) {
            throw new IllegalArgumentException("Vui lòng cung cấp link họp trực tuyến hoặc địa điểm phòng tư vấn.");
        }
        LichHenTuVan app = appointmentRepo.findById(maLichHen).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy lịch hẹn."));
        requireAppointmentAdvisor(app, maCV);
        if (!"ChoDuyet".equals(app.getTrangThai())) {
            throw new IllegalStateException("Chỉ có thể phê duyệt lịch hẹn đang chờ duyệt.");
        }
        LocalDateTime now = LocalDateTime.now();
        app.setTrangThai("DaXacNhan");
        app.setLinkHopPhong(linkHopPhong.trim());
        app.setNgayDuyet(now);
        appointmentRepo.save(app);
        // Báo cho sinh viên
        notificationService.sendNotification(app.getSinhVien().getTaiKhoan(), "Lịch hẹn tư vấn đã được xác nhận!", "Buổi tư vấn \'" + app.getChuDe() + "\' đã được xác nhận. Phòng/Link: " + linkHopPhong, "LichHen", "/student/appointments");
    }

    @Transactional
    public void rejectAppointment(Integer maLichHen, Integer maCV, String lyDo) {
        if (lyDo == null || lyDo.trim().isEmpty()) {
            throw new IllegalArgumentException("Vui lòng nhập lý do từ chối lịch hẹn.");
        }
        LichHenTuVan app = appointmentRepo.findById(maLichHen).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy lịch hẹn."));
        requireAppointmentAdvisor(app, maCV);
        if (!"ChoDuyet".equals(app.getTrangThai())) {
            throw new IllegalStateException("Chỉ có thể từ chối lịch hẹn đang chờ duyệt.");
        }
        LocalDateTime now = LocalDateTime.now();
        app.setTrangThai("TuChoi");
        app.setLyDo(lyDo.trim());
        app.setNgayDuyet(now);
        appointmentRepo.save(app);
        // Báo cho sinh viên
        notificationService.sendNotification(app.getSinhVien().getTaiKhoan(), "Lịch hẹn tư vấn bị từ chối", "Buổi tư vấn \'" + app.getChuDe() + "\' không được duyệt. Lý do: " + lyDo, "LichHen", "/student/appointments");
    }

    @Transactional
    public void completeAppointment(Integer maLichHen, Integer maCV, String ketLuan) {
        if (ketLuan == null || ketLuan.trim().isEmpty()) {
            throw new IllegalArgumentException("Vui lòng ghi nhận kết luận buổi tư vấn.");
        }
        LichHenTuVan app = appointmentRepo.findById(maLichHen).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy lịch hẹn."));
        requireAppointmentAdvisor(app, maCV);
        if (!"DaXacNhan".equals(app.getTrangThai())) {
            throw new IllegalStateException("Chỉ có thể hoàn thành buổi hẹn đã được xác nhận.");
        }
        if (LocalDateTime.now().isBefore(app.getKhungGio().getKetThuc())) {
            throw new IllegalStateException("Chỉ được hoàn thành lịch hẹn sau khi khung giờ tư vấn kết thúc.");
        }
        LocalDateTime now = LocalDateTime.now();
        app.setTrangThai("HoanThanh");
        app.setKetLuan(ketLuan.trim());
        app.setNgayHoanThanh(now);
        appointmentRepo.save(app);
        // Nhắc sinh viên đánh giá
        notificationService.sendNotification(app.getSinhVien().getTaiKhoan(), "Buổi tư vấn đã hoàn thành", "Buổi tư vấn \'" + app.getChuDe() + "\' đã hoàn tất. Xin mời bạn đánh giá chất lượng tư vấn.", "LichHen", "/student/appointments");
    }

    @Transactional
    public void cancelAppointment(Integer maLichHen, Integer maSV, String lyDo) {
        if (lyDo == null || lyDo.trim().isEmpty()) {
            throw new IllegalArgumentException("Vui lòng cung cấp lý do hủy hẹn.");
        }
        LichHenTuVan app = appointmentRepo.findById(maLichHen).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy lịch hẹn."));
        if (!app.getSinhVien().getMaSV().equals(maSV)) {
            throw new IllegalArgumentException("Bạn chỉ có thể hủy lịch hẹn của chính mình.");
        }
        if (!"ChoDuyet".equals(app.getTrangThai()) && !"DaXacNhan".equals(app.getTrangThai())) {
            throw new IllegalStateException("Không thể hủy lịch hẹn ở trạng thái này.");
        }
        // Kiểm tra hủy trước ít nhất 12 giờ
        LocalDateTime now = LocalDateTime.now();
        if (app.getKhungGio().getBatDau().isBefore(now.plusHours(12))) {
            throw new IllegalStateException("Theo quy chế, bạn chỉ có thể hủy lịch hẹn trước ít nhất 12 giờ so với thời điểm diễn ra.");
        }
        app.setTrangThai("Huy");
        app.setLyDo(lyDo.trim());
        appointmentRepo.save(app);
        // Báo cho cố vấn
        notificationService.sendNotification(app.getNguoiTuVan().getTaiKhoan(), "Sinh viên đã hủy lịch hẹn", "Sinh viên " + app.getSinhVien().getTaiKhoan().getHoTen() + " đã hủy lịch hẹn \'" + app.getChuDe() + "\'.", "LichHen", "/advisor/appointments");
    }

    @Transactional
    public void rateAppointment(Integer maLichHen, Integer maSV, Short soSao, String nhanXet) {
        if (soSao == null || soSao < 1 || soSao > 5) {
            throw new IllegalArgumentException("Điểm đánh giá phải từ 1 đến 5 sao.");
        }
        LichHenTuVan app = appointmentRepo.findById(maLichHen).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy lịch hẹn."));
        if (!app.getSinhVien().getMaSV().equals(maSV)) {
            throw new IllegalArgumentException("Bạn chỉ có thể đánh giá lịch hẹn của chính mình.");
        }
        if (!"HoanThanh".equals(app.getTrangThai())) {
            throw new IllegalStateException("Chỉ có thể đánh giá buổi tư vấn đã hoàn thành.");
        }
        if (ratingRepo.existsByLichHen_MaLichHen(maLichHen)) {
            throw new IllegalStateException("Buổi tư vấn này đã được đánh giá rồi (không thể sửa đổi).");
        }
        DanhGiaBuoiTuVan dg = DanhGiaBuoiTuVan.builder().lichHen(app).maSV(maSV).soSao(soSao).nhanXet(nhanXet != null ? nhanXet.trim() : "").ngayDanhGia(LocalDateTime.now()).build();
        ratingRepo.save(dg);
    }

    public List<LichHenTuVan> getStudentAppointments(Integer maSV) {
        return appointmentRepo.findBySinhVien_MaSVOrderByNgayTaoDesc(maSV);
    }

    public List<LichHenTuVan> getAdvisorAppointments(Integer maCV) {
        return appointmentRepo.findByNguoiTuVan_MaCVOrderByNgayTaoDesc(maCV);
    }

    private void requireAppointmentAdvisor(LichHenTuVan appointment, Integer maCV) {
        if (maCV == null || !appointment.getNguoiTuVan().getMaCV().equals(maCV)) {
            throw new SecurityException("Bạn không có quyền xử lý lịch hẹn của cố vấn khác.");
        }
    }

    public List<KhungGioTuVan> getAdvisorSlots(Integer maCV) {
        return slotRepo.findByNguoiTuVan_MaCVOrderByBatDauAsc(maCV);
    }

    @java.lang.SuppressWarnings("all")
    @lombok.Generated
    public AppointmentService(final KhungGioTuVanRepository slotRepo, final LichHenTuVanRepository appointmentRepo, final DanhGiaBuoiTuVanRepository ratingRepo, final NotificationService notificationService) {
        this.slotRepo = slotRepo;
        this.appointmentRepo = appointmentRepo;
        this.ratingRepo = ratingRepo;
        this.notificationService = notificationService;
    }
}
